using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;using RaceDay.Mvc.Models;namespace RaceDay.Mvc.Controllers;public class OrganiserController(RaceApi api):Controller{bool OkRole()=>HttpContext.Session.GetString("role")=="Organiser";public async Task<IActionResult> Events(){if(!OkRole())return Forbid();var es=await api.Get<List<RaceEvent>>("api/events")??new();return View(es.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("userId")).ToList());}public IActionResult Create()=>OkRole()?View("Form",new EventForm()):Forbid();[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Create(EventForm f)=>await Save(f,false);public async Task<IActionResult> Edit(int id){if(!OkRole())return Forbid();var details=await api.Get<EventDetails>("api/events/"+id);var e=details?.Event;return e==null?NotFound():View("Form",new EventForm{EventId=e.EventId,EventName=e.EventName,Description=e.Description,EventDate=e.EventDate,Venue=e.Venue,City=e.City,Province=e.Province,EventType=e.EventType,Status=e.Status});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(EventForm f)=>await Save(f,true);async Task<IActionResult> Save(EventForm f,bool edit){if(!OkRole())return Forbid();if(!ModelState.IsValid)return View("Form",f);var body=new{f.EventName,f.Description,f.EventDate,f.Venue,f.City,f.Province,f.EventType,f.Status};var r=await api.Send(edit?HttpMethod.Put:HttpMethod.Post,edit?$"api/events/{f.EventId}":"api/events",body);TempData["Notice"]=r.ok?"Event saved.":r.error;return RedirectToAction(nameof(Events));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){if(!OkRole())return Forbid();var r=await api.Send(HttpMethod.Delete,$"api/events/{id}");TempData["Notice"]=r.ok?"Event deleted.":r.error;return RedirectToAction(nameof(Events));}public async Task<IActionResult> Categories(int id){if(!OkRole())return Forbid();ViewBag.Id=id;ViewBag.Event=await api.Get<RaceEvent>($"api/events/{id}");return View(await api.Get<List<Category>>($"api/events/{id}/categories")??new());}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AddCategory(int id,string categoryName,decimal distanceKm,decimal entryFee,int? maximumParticipants){if(!OkRole())return Forbid();var r=await api.Send(HttpMethod.Post,$"api/events/{id}/categories",new{categoryName,distanceKm,entryFee,maximumParticipants});TempData["Notice"]=r.ok?"Category added.":r.error;return RedirectToAction(nameof(Categories),new{id});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> UpdateCategory(int id,int eventId,string categoryName,decimal distanceKm,decimal entryFee,int? maximumParticipants){if(!OkRole())return Forbid();var r=await api.Send(HttpMethod.Put,$"api/categories/{id}",new{categoryName,distanceKm,entryFee,maximumParticipants});TempData["Notice"]=r.ok?"Category updated.":r.error;return RedirectToAction(nameof(Categories),new{id=eventId});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteCategory(int id,int eventId){if(!OkRole())return Forbid();var r=await api.Send(HttpMethod.Delete,$"api/categories/{id}");TempData["Notice"]=r.ok?"Category deleted.":r.error;return RedirectToAction(nameof(Categories),new{id=eventId});}public async Task<IActionResult> Enrolments(int id){if(!OkRole())return Forbid();ViewBag.Event=await api.Get<RaceEvent>($"api/events/{id}");return View(await api.Get<List<Enrolment>>($"api/events/{id}/enrolments")??new());}public async Task<IActionResult> Results(int id){if(!OkRole())return Forbid();ViewBag.Event=await api.Get<RaceEvent>($"api/events/{id}");ViewBag.Entries=await api.Get<List<Enrolment>>($"api/events/{id}/enrolments")??new();return View(await api.Get<List<RaceResult>>($"api/events/{id}/results")??new());}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> PublishResult(int id,int enrolmentId,int? finishPosition,int? finishTimeSeconds,string resultStatus){if(!OkRole())return Forbid();var r=await api.Send(HttpMethod.Post,$"api/events/{id}/results",new{enrolmentId,finishPosition,finishTimeSeconds,resultStatus});TempData["Notice"]=r.ok?"Result published.":r.error;return RedirectToAction(nameof(Results),new{id});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Banner(int id,IFormFile file){if(!OkRole())return Forbid();var r=await api.Upload($"api/files/event-banner?eventId={id}",file);TempData["Notice"]=r.ok?"Banner uploaded.":r.error;return RedirectToAction(nameof(Events));}}